package com.lacoste.verification; import android.content.*; import com.google.firebase.*; public final class FirebaseConfig { public static void init(Context c){try{if(FirebaseApp.getApps(c).size()>0)return;FirebaseOptions o=new FirebaseOptions.Builder().setApiKey(BuildConfig.FIREBASE_API_KEY).setApplicationId(BuildConfig.FIREBASE_APP_ID).setProjectId(BuildConfig.FIREBASE_PROJECT_ID).setGcmSenderId(BuildConfig.FIREBASE_MESSAGING_SENDER_ID).build();FirebaseApp.initializeApp(c,o);}catch(Exception ignored){}}}
